css:
/* ÖkoInvest – gemeinsames Druck-Stylesheet aller Druckformate (wird per werkzeuge/bauen.py in jede Print-Format-JSON übernommen).
   Farben: Grün #669933, Navy #003473; Schriften: Manrope (Überschriften) / Inter mit Systemschrift-Fallbacks (keine externen Fonts, wkhtmltopdf offline). */
.print-format { font-family: Inter, "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: 9.5pt; color: #1f2933; line-height: 1.45; padding: 0; }
.print-format h1, .print-format h2, .print-format h3, .oi-titel { font-family: Manrope, Inter, "Helvetica Neue", Arial, sans-serif; color: #003473; margin: 0; }
.oi-kopf { border-bottom: 3px solid #669933; padding-bottom: 8px; margin-bottom: 14px; }
.oi-ueberzeile { font-size: 7.5pt; letter-spacing: .12em; text-transform: uppercase; color: #669933; font-weight: 700; margin-bottom: 2px; }
.oi-titel { font-size: 17pt; font-weight: 800; line-height: 1.2; }
.oi-untertitel { font-size: 9.5pt; color: #52606d; margin-top: 3px; }
.oi-marke { font-family: Manrope, Inter, Arial, sans-serif; font-weight: 800; color: #003473; }
.oi-marke b { color: #669933; }
.oi-abschnitt { margin: 14px 0 6px; font-family: Manrope, Inter, Arial, sans-serif; font-size: 11pt; font-weight: 700; color: #003473; border-bottom: 1px solid #d9e2d0; padding-bottom: 3px; page-break-after: avoid; }
.oi-tabelle { width: 100%; border-collapse: collapse; margin: 4px 0 8px; }
.oi-tabelle th { text-align: left; font-size: 8pt; text-transform: uppercase; letter-spacing: .04em; color: #52606d; background: #f3f6ef; border-bottom: 1px solid #c9d6bb; padding: 5px 6px; }
.oi-tabelle td { border-bottom: 1px solid #e6ebe1; padding: 5px 6px; vertical-align: top; }
.oi-tabelle td.oi-zahl, .oi-tabelle th.oi-zahl { text-align: right; white-space: nowrap; }
.oi-daten { width: 100%; border-collapse: collapse; }
.oi-daten td { padding: 3px 6px 3px 0; vertical-align: top; }
.oi-daten td.oi-feld { width: 38%; color: #52606d; }
.oi-kacheln { width: 100%; border-collapse: separate; border-spacing: 6px 0; margin: 6px -6px 10px; }
.oi-kachel { background: #f3f6ef; border-radius: 10px; padding: 8px 10px; }
.oi-kachel .oi-wert { font-family: Manrope, Inter, Arial, sans-serif; font-size: 15pt; font-weight: 800; color: #003473; }
.oi-kachel .oi-bez { font-size: 7.5pt; color: #52606d; text-transform: uppercase; letter-spacing: .05em; }
.oi-hinweis { background: #f3f6ef; border-left: 3px solid #669933; padding: 7px 10px; margin: 8px 0; font-size: 8.5pt; }
.oi-warnung { background: #fff6e5; border-left: 3px solid #c98a00; padding: 7px 10px; margin: 8px 0; font-size: 8.5pt; }
.oi-vertraulich { border: 1.5px solid #003473; color: #003473; font-weight: 700; font-size: 8pt; letter-spacing: .08em; text-transform: uppercase; padding: 4px 8px; display: inline-block; border-radius: 6px; }
.oi-badge { display: inline-block; padding: 1px 7px; border-radius: 999px; font-size: 8pt; font-weight: 600; background: #e7efdd; color: #3d5c1f; }
.oi-badge.oi-rot { background: #fde8e8; color: #9b1c1c; }
.oi-badge.oi-gelb { background: #fff3d6; color: #7a5200; }
.oi-badge.oi-navy { background: #e3eaf4; color: #003473; }
.oi-text { white-space: pre-wrap; }
.oi-klein { font-size: 8pt; color: #52606d; }
.oi-absatz { margin: 0 0 7px; text-align: justify; }
.oi-unterschrift { width: 100%; margin-top: 34px; border-collapse: collapse; }
.oi-unterschrift td { width: 50%; padding: 0 18px 0 0; vertical-align: bottom; }
.oi-linie { border-top: 1px solid #1f2933; padding-top: 3px; font-size: 8pt; color: #52606d; }
.oi-protokoll { page-break-before: always; }
.oi-fuss { margin-top: 18px; border-top: 1px solid #d9e2d0; padding-top: 5px; font-size: 7.5pt; color: #7b8794; }
.oi-seitenumbruch { page-break-before: always; }
.oi-muster { position: relative; }
.oi-muster-stempel { border: 2px dashed #c98a00; color: #7a5200; padding: 6px 10px; font-weight: 700; margin-bottom: 10px; font-size: 8.5pt; }

html:
{#- ÖkoInvest – Anlagen-Datenblatt (Plattform Anlage) mit Komponenten, Messpunkten, Vertrag, Wartung und offenen Störungen. -#}
{%- set f = oekoinvest_firma() -%}
{%- set d = oekoinvest_anlage(doc.name) -%}
{%- set kunde = oekoinvest_konto(doc.kunde_id) if doc.kunde_id else None -%}
{% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}
<div class="oi-kopf">
	<div class="oi-ueberzeile">Anlagen & Betrieb · Datenblatt</div>
	<div class="oi-titel">{{ doc.titel | e }}</div>
	<div class="oi-untertitel">Anlage {{ doc.name }} · {{ oekoinvest_label("anlage_typ", doc.typ) }} · {{ oekoinvest_label("anlage_status", doc.status) }}</div>
</div>

<table class="oi-kacheln"><tr>
	<td class="oi-kachel"><div class="oi-wert">{{ oekoinvest_zahl(doc.kwp, 1) }}</div><div class="oi-bez">kWp</div></td>
	<td class="oi-kachel"><div class="oi-wert">{{ oekoinvest_zahl(doc.speicher_kwh, 0) if doc.speicher_kwh else "–" }}</div><div class="oi-bez">kWh Speicher</div></td>
	<td class="oi-kachel"><div class="oi-wert">{{ doc.wechselrichter_anzahl or "–" }}</div><div class="oi-bez">Wechselrichter</div></td>
	<td class="oi-kachel"><div class="oi-wert" style="font-size:11pt">{{ oekoinvest_datum(doc.inbetriebnahme) }}</div><div class="oi-bez">Inbetriebnahme</div></td>
</tr></table>

<div class="oi-abschnitt">Stammdaten</div>
<table class="oi-daten">
	<tr><td class="oi-feld">Standort</td><td>{{ doc.ort | e }}{% if doc.bundesland %}, {{ doc.bundesland | e }}{% endif %} ({{ oekoinvest_label("land", doc.land) }})</td></tr>
	<tr><td class="oi-feld">Kunde</td><td>{% if kunde %}{{ (kunde.firma or kunde.name) | e }}{% else %}–{% endif %}</td></tr>
	<tr><td class="oi-feld">Lastprofil</td><td>{{ oekoinvest_label("lastprofil", doc.lastprofil) }}{% if doc.last_jahr_kwh %} · {{ oekoinvest_zahl(doc.last_jahr_kwh) }} kWh/Jahr{% endif %}</td></tr>
	<tr><td class="oi-feld">Speicherleistung</td><td>{{ oekoinvest_zahl(doc.speicher_kw, 0) ~ " kW" if doc.speicher_kw else "–" }}</td></tr>
</table>
{% if doc.beschreibung %}<p class="oi-text">{{ doc.beschreibung | e }}</p>{% endif %}

{% if d.komponenten %}
<div class="oi-abschnitt">Komponenten</div>
<table class="oi-tabelle">
	<tr><th>Art</th><th>Hersteller / Modell</th><th>Seriennummer</th><th class="oi-zahl">Anzahl</th><th class="oi-zahl">Leistung / Kapazität</th><th>Garantie bis</th></tr>
	{% for k in d.komponenten %}<tr><td>{{ oekoinvest_label("komponente", k.art) }}</td><td>{{ k.hersteller | e }} {{ k.modell | e }}</td><td>{{ (k.seriennummer or "–") | e }}</td><td class="oi-zahl">{{ k.anzahl or 1 }}</td><td class="oi-zahl">{% if k.leistung_kw %}{{ oekoinvest_zahl(k.leistung_kw, 1) }} kW{% endif %}{% if k.kapazitaet_kwh %} {{ oekoinvest_zahl(k.kapazitaet_kwh, 0) }} kWh{% endif %}</td><td>{{ oekoinvest_datum(k.garantie_bis) }}</td></tr>{% endfor %}
</table>
{% endif %}
{% if d.messpunkte %}
<div class="oi-abschnitt">Messpunkte</div>
<table class="oi-tabelle">
	<tr><th>Bezeichnung</th><th>Zählernummer</th><th>Art</th><th>Messstelle</th><th>Abrechnung</th><th>Eichung bis</th></tr>
	{% for m in d.messpunkte %}<tr><td>{{ m.bezeichnung | e }}</td><td>{{ (m.zaehlernummer or "–") | e }}</td><td>{{ oekoinvest_label("messpunkt_art", m.art) }}</td><td>{{ oekoinvest_label("messstelle", m.messstelle) }}{% if m.smgw %} · SMGW{% endif %}</td><td>{{ "ja" if m.abrechnungsrelevant else "nein" }}</td><td>{{ oekoinvest_datum(m.eichgueltig_bis) }}</td></tr>{% endfor %}
</table>
{% endif %}
{% if d.vertraege %}
<div class="oi-abschnitt">Contracting-Vertrag</div>
<table class="oi-tabelle">
	<tr><th>Nummer</th><th>Beginn</th><th class="oi-zahl">Laufzeit</th><th class="oi-zahl">Arbeitspreis</th><th class="oi-zahl">Grundgebühr</th><th class="oi-zahl">Indexierung</th><th>Status</th></tr>
	{% for v in d.vertraege %}<tr><td>{{ (v.nummer or "–") | e }}</td><td>{{ oekoinvest_datum(v.beginn) }}</td><td class="oi-zahl">{{ v.laufzeit_jahre or "–" }} J.</td><td class="oi-zahl">{{ oekoinvest_zahl(v.strompreis_ct, 2) }} ct/kWh</td><td class="oi-zahl">{{ oekoinvest_eur(v.grundgebuehr_monat, 2) }}/Monat</td><td class="oi-zahl">{{ oekoinvest_zahl(v.indexierung_pct, 1) }} %</td><td>{{ v.status }}</td></tr>{% endfor %}
</table>
{% endif %}
{% if d.wartungen %}
<div class="oi-abschnitt">Wartung</div>
<table class="oi-tabelle">
	<tr><th>Art</th><th>Datum</th><th>Status</th><th>Dienstleister</th><th>Nächste Fälligkeit</th></tr>
	{% for w in d.wartungen[:10] %}<tr><td>{{ oekoinvest_label("wartung_art", w.art) }}</td><td>{{ oekoinvest_datum(w.datum) }}</td><td>{{ oekoinvest_label("wartung_status", w.status) }}</td><td>{{ (w.dienstleister or "–") | e }}</td><td>{{ oekoinvest_datum(w.naechste_faelligkeit) }}</td></tr>{% endfor %}
</table>
{% endif %}
<div class="oi-abschnitt">Offene Störungen</div>
{% if d.stoerungen %}
<table class="oi-tabelle">
	<tr><th>Störung</th><th>Titel</th><th>Schwere</th><th>Status</th><th>Erkannt</th></tr>
	{% for s in d.stoerungen %}<tr><td>{{ s.name }}</td><td>{{ s.titel | e }}</td><td>{{ oekoinvest_label("schwere", s.schwere) }}</td><td>{{ oekoinvest_label("stoerung_status", s.status) }}</td><td>{{ oekoinvest_datum(s.erkannt_am, true) }}</td></tr>{% endfor %}
</table>
{% else %}<p class="oi-klein">Keine offenen Störungen.</p>{% endif %}
<div class="oi-fuss">{{ f.name }} · {{ f.strasse }} · {{ f.ort }} · {{ f.fn }} · Stand {{ oekoinvest_datum(frappe.utils.now_datetime(), true) }}</div>
